       )
       or pg_catalog.has_schema_privilege(
           'anon', to_regnamespace('operator_private'), 'usage'
       )
       or pg_catalog.has_schema_privilege(
           'anon', to_regnamespace('operator_private'), 'create'
       )
       or pg_catalog.has_schema_privilege(
           'authenticated', to_regnamespace('operator_private'), 'usage'
